use mars_core::{
    World,
    engine::Engine,
    synth::{self, SynthSpec},
};
use std::path::Path;

pub fn load_engine(data_dir: &Path) -> Engine {
    let world = if data_dir.join("meta.json").exists() {
        match World::load_processed(data_dir) {
            Ok(w) => w,
            Err(e) => {
                eprintln!(
                    "[mars-server] failed to load {}: {e:#}; falling back to synthetic terrain",
                    data_dir.display()
                );
                synth::generate(&SynthSpec::default())
            }
        }
    } else {
        synth::generate(&SynthSpec::default())
    };
    Engine::new(world)
}
